import xatlas,numpy as np,json,time
from pathlib import Path
root=Path.home()/'Documents/undertaker-wool-pbr';data=np.load(root/'uv_input.npz');atlas=xatlas.Atlas();atlas.add_mesh(data['vertices'],data['faces']);charts=xatlas.ChartOptions();charts.max_iterations=4;pack=xatlas.PackOptions();pack.resolution=2048;pack.padding=3;pack.bilinear=True;pack.rotate_charts=True;start=time.perf_counter();atlas.generate(chart_options=charts,pack_options=pack);mapping,indices,uv=atlas[0];assert np.array_equal(mapping[indices],data['faces']);np.savez(root/'uv_xatlas.npz',mapping=mapping,indices=indices,uv=uv);report={'seconds':time.perf_counter()-start,'utilization':atlas.utilization,'width':atlas.width,'height':atlas.height,'chart_count':atlas.chart_count};(root/'uv_report.json').write_text(json.dumps(report,indent=2));print(report)
